import{z as l,x as A,o,c as d,q as i,j as s,D as r,d as E,s as n,S as B,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"披露理论","description":"","frontmatter":{"title":"披露理论","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/disclosure-theory.md","filePath":"econ/disclosure-theory.md","lastUpdated":1791063341000}'),p={name:"econ/disclosure-theory.md"};function c(m,a,h,D,u,f){const t=A("Mermaid");return o(),d("div",null,[a[2]||(a[2]=i('<h1 id="披露理论" tabindex="-1">披露理论 <a class="header-anchor" href="#披露理论" aria-label="Permalink to &quot;披露理论&quot;">​</a></h1><div class="epigraph"><p>能被验证的好消息会被说出来；沉默在均衡里被读成坏消息，直到全部揭开——除非披露本身有成本或有接收端的摩擦。</p><footer>—— Grossman, The Informational Role of Warranties and Private Disclosure about Product Quality, Journal of Law and Economics, 1981；Milgrom, Good News and Bad News, Bell Journal, 1981</footer></div><p><a href="/econ/asymmetric-info-liquidity">上一课</a>里信息通过交易泄漏，价差是保险费。本课缺口是<strong>主动开口</strong>：持有可验证信号的人，要不要把它变成 Morris–Shin 意义上的公共 \\(y\\)。不重写报价的贝叶斯，不把披露写成监管清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>卖方（或经理）看见质量或 \\(\\theta\\)，买方只见披露与否。若披露可验证、成本为零，好类型有激励说出自己，以区别于较差类型；买方把沉默解释为「还不够好」，于是次好者也说——逆向归纳把除最差以外全部揭开。Grossman（1981）、Milgrom（1981）的揭开（unraveling）是柠檬市场的对偶：Akerlof 里质量不可验证，坏货驱逐好货；这里可验证，好货驱逐沉默。</p><p>缺口是：为何现实不是完全披露。成本（准备、专有信息泄漏给对手）、接收端不确定（Dye：买方不知道你有没有信号）、或验证只能到区间，都会在中间截断。Verrecchia 把披露成本写成阈值：只有 \\(\\theta\\) 高过阈值才开口，价格对沉默打一个条件期望的折。</p><p><span class="marginnote">与上一课程有限注意力对照：揭开假定接收端读得懂。注意力预算会阻断逆向归纳——沉默不再充分统计「最差」，因为也可能是「没被读到」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>验证披露：消息一旦说出即被相信。均衡是阈值或完全揭开。把披露接到资产定价：公开 \\(y\\) 改变后验，也改变不利选择（知情交易者的信息优势下降，价差可收）。但 Morris–Shin 警告：若定价含协调，多一条公共 \\(y\\) 不必改进福利。本课把两股力并列，不让其中一句吞掉另一句。</p><p>策略性补充：只披露好的可验证部分、把坏的留在交易泄漏里。此时价差与公告并存——公告不是信息的全部通道。GS 采集仍在后台：披露改变的是公共与私有的分界，不是采集成本本身。</p>',10)),(o(),s(B,null,{default:r(()=>[n(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20VER%5B%22%E5%8F%AF%E9%AA%8C%E8%AF%81%E3%80%81%E9%9B%B6%E6%88%90%E6%9C%AC%22%5D%20--%3E%20UNR%5B%22%E6%8F%AD%E5%BC%80%3A%20%E6%B2%89%E9%BB%98%20%3D%20%E6%9C%80%E5%B7%AE%22%5D%0A%20%20COST%5B%22%E6%8A%AB%E9%9C%B2%E6%88%90%E6%9C%AC%22%5D%20--%3E%20THR%5B%22%E9%98%88%E5%80%BC%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20DYE%5B%22%E6%8E%A5%E6%94%B6%E7%AB%AF%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%9C%89%E6%97%A0%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20PART%5B%22%E9%83%A8%E5%88%86%E6%B2%89%E9%BB%98%E4%B8%8D%E6%98%AF%E6%9C%80%E5%B7%AE%22%5D%0A%20%20THR%20--%3E%20Y%5B%22%E5%85%AC%E5%85%B1%20y%22%5D%0A%20%20Y%20--%3E%20SPR%5B%22%E4%B8%8D%E5%88%A9%E9%80%89%E6%8B%A9%E5%8F%AF%E5%8F%98%22%5D%0A%20%20Y%20--%3E%20MS%5B%22%E5%8D%8F%E8%B0%83%E4%B8%8B%E7%A6%8F%E5%88%A9%E4%B8%8D%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[E("不要把强制披露写成「所以价格更有效」的实证结论。强制把阈值推低，改变的是谁开口；有效仍相对信息集，且联合着 "),e("a",{href:"/econ/stochastic-discount-factor"},"SDF"),E(" 的风险调整。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"揭开的机制是信念的逆向归纳，与信号博弈的直觉准则同族：好类型有便宜的分离动作（说出可验证的好），沉默无法被好类型使用。成本破坏便宜：中等类型觉得开口的专有成本高于分离收益，池定在沉默。买方理性地给沉默一个截断分布的均值，不是给零。",-1)),(o(),s(B,null,{default:r(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEST%5B%22%E6%9C%80%E5%A5%BD%E7%9A%84%E7%B1%BB%E5%9E%8B%3A%20%E5%BC%80%E5%8F%A3%E9%9B%B6%E6%88%90%E6%9C%AC%E4%B8%94%E8%83%BD%E5%88%86%E7%A6%BB%22%5D%20--%3E%20SP%5B%22%E5%85%88%E5%BC%80%E5%8F%A3%22%5D%0A%20%20SP%20--%3E%20MID%5B%22%E6%AC%A1%E5%A5%BD%E8%80%85%3A%20%E6%B2%89%E9%BB%98%E7%8E%B0%E5%9C%A8%E5%8F%AA%E5%B1%9E%E4%BA%8E%E8%BE%83%E5%B7%AE%E8%80%85%22%5D%0A%20%20MID%20--%3E%20SP2%5B%22%E4%B9%9F%E8%A2%AB%E8%BF%AB%E5%BC%80%E5%8F%A3%22%5D%0A%20%20SP2%20--%3E%20DOWN%5B%22%E9%80%90%E7%BA%A7%E4%B8%8B%E6%8E%A8%3A%20%E5%8F%AA%E5%89%A9%E6%9C%80%E5%B7%AE%E4%BB%8D%E6%B2%89%E9%BB%98%22%5D%0A%20%20DOWN%20--%3E%20READ%5B%22%E4%B9%B0%E6%96%B9%E6%8A%8A%E6%B2%89%E9%BB%98%E8%AF%BB%E6%88%90%E6%9C%80%E5%B7%AE%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p><span class="marginnote">「揭开效应」（unraveling）就是：只要亮出好消息免费且可信，竞争会逼着所有人亮牌——最好的先亮，次好的被迫跟，最后「不亮」本身成了坏消息。可以类比招聘市场：一旦贴薪资范围免费且可信，敢不贴薪资的岗位会被默认读成「给不起」。</span></p><p>与柠檬的关系：不可验证时开口无用，市场靠价格推测平均质量，可以关闭。可验证时开口太有用，市场几乎不让你闭嘴。中间地带——半可验证、有成本、有注意力——才是工作理论。</p><p><span class="marginnote">常见误区：以为「沉默 = 最差类型」是说公司一文不值。准确说法是：买方对沉默的定价等于「在所有没开口的类型里取条件平均」。若只有最差的三成保持沉默，沉默的定价就是这三成的均值——比零高，但比全场平均低。</span></p><p><span class="marginnote">Jovanovic、Verrecchia 的自愿披露，Dye 的「投资者不知道经理有没有消息」，是截断而不是否定揭开。强制披露的理论价值，是在这些摩擦上移动阈值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写会计准则条文，不估计公告窗口。下一课把开口外包：评级、分析师、审计，作为生产 \\(y\\) 的中介。企业自己的阈值与中介的激励是两套委托。</p><p><span class="marginnote">初学者容易把「强制披露」当成免费的福利改进。理论提醒有两层摩擦：披露有真实成本（专有信息泄给对手），且多一条公共信息在协调场景下未必改进福利（Morris–Shin）。强制披露做的是移动阈值、改换谁开口，不是抹掉信息的社会成本。</span></p><p>也不要把披露当成限价簿上的「展示冰山」。展示是协议选择；披露是关于 \\(\\theta\\) 的可验证陈述。切点仍在 <a href="/econ/to-limit-order-book">到限价簿</a>。</p><p>后课默认：可验证零成本则揭开；成本与接收摩擦给出阈值。公共 \\(y\\) 改变不利选择，福利还要过 Morris–Shin 那一关。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可验证、零成本：逆向归纳揭开，沉默等于最差。</li><li>成本或「不知有无信号」截断披露，沉默对应一个条件期望。</li><li>公告与交易泄漏是两条通道，不是互斥。</li><li>出处：Grossman, <em>JLE</em> 1981；Milgrom, <em>Bell</em> 1981；Verrecchia；Dye。</li></ul>',11))])}const _=l(p,[["render",c]]);export{S as __pageData,_ as default};
